WITH valid AS (SELECT id, product_name, category, brand, price, cost, stock_qty, launch_date, tags, stock_qty * price AS stock_qty_times_price FROM products WHERE brand IS NOT NULL), with_windows AS (SELECT *, SUM(price) OVER w_grp AS running_price, ROW_NUMBER() OVER (PARTITION BY brand ORDER BY stock_qty, id) AS row_seq, RANK() OVER (PARTITION BY brand, category ORDER BY stock_qty NULLS FIRST) AS stock_qty_rank, FIRST_VALUE(stock_qty_times_price) IGNORE NULLS OVER (PARTITION BY category ORDER BY stock_qty_times_price, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS first_known_stock_qty_times_price, LAST_VALUE(cost, TRUE) OVER w_hist AS last_known_cost FROM valid WINDOW w_grp AS (ORDER BY stock_qty_times_price, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW), w_hist AS (PARTITION BY category ORDER BY stock_qty, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW)), metrics AS (SELECT id, product_name, cost, running_price, row_seq, stock_qty_rank, MAX(running_price) OVER (PARTITION BY brand ORDER BY stock_qty_times_price, id ROWS BETWEEN 3 PRECEDING AND CURRENT ROW) AS last4_max_running_price, SUM(running_price) OVER (PARTITION BY brand ORDER BY stock_qty_times_price, id ROWS BETWEEN 3 PRECEDING AND CURRENT ROW) AS last4_sum_running_price, MIN(running_price) OVER (PARTITION BY brand ORDER BY stock_qty_times_price, id ROWS BETWEEN 3 PRECEDING AND CURRENT ROW) AS last4_min_running_price FROM with_windows), latest_match AS (SELECT s.id, s.cost, s.running_price, s.row_seq, s.stock_qty_rank, s.last4_max_running_price, s.last4_sum_running_price, top1.inventory_last_restock FROM metrics s LEFT JOIN LATERAL (SELECT c.last_restock AS inventory_last_restock FROM inventory c WHERE c.product_id = s.id ORDER BY c.last_restock DESC, c.id DESC LIMIT 1) top1 ON TRUE), latest_match_products AS (SELECT s.*, latest.quantity, latest.last_restock FROM latest_match s LEFT JOIN LATERAL (SELECT c.quantity, c.last_restock FROM inventory c WHERE c.product_id = s.id ORDER BY c.quantity DESC, c.id DESC LIMIT 1) latest ON TRUE), with_last AS (SELECT s.*, top1.inventory_quantity, top1.inventory_last_restock_2 FROM latest_match_products s JOIN LATERAL (SELECT c.quantity AS inventory_quantity, c.last_restock AS inventory_last_restock_2 FROM inventory c WHERE c.product_id = s.id ORDER BY c.quantity DESC, c.id DESC LIMIT 1) top1 ON TRUE), with_latest AS (SELECT s.id, s.last4_max_running_price, s.inventory_last_restock, s.quantity, s.inventory_quantity, x.inventory_quantity_2, x.inventory_last_restock_3 FROM with_last s JOIN LATERAL (SELECT c.quantity AS inventory_quantity_2, c.last_restock AS inventory_last_restock_3 FROM inventory c WHERE c.product_id = s.id ORDER BY c.last_restock DESC, c.id DESC LIMIT 1) x ON TRUE) SELECT CASE WHEN last4_max_running_price >= 6500 THEN 'LARGE' ELSE 'SMALL' END AS last4_max_running_price_tier, COUNT(*) AS row_count, ROUND(AVG(inventory_quantity), 2) AS avg_inventory_quantity, PERCENTILE_APPROX(inventory_quantity_2, ARRAY(0.25, 0.5, 0.75)) AS inventory_quantity_2_quartiles FROM with_latest GROUP BY CASE WHEN last4_max_running_price >= 6500 THEN 'LARGE' ELSE 'SMALL' END
